const complex = document.getElementById('complex-para');
if (!complex) return false;
const btn = complex.nextElementSibling;
if (!btn || !btn.classList.contains('ai4a11y-plain-btn')) return true; // before enable

const originalText = complex.textContent;

// Click with AI unavailable
await window.__verifyClick('#complex-para + .ai4a11y-plain-btn');
await new Promise((r) => setTimeout(r, 350));

// Paragraph must remain visible and unchanged
if (complex.hasAttribute('hidden')) return false;
if (complex.textContent !== originalText) return false;

// No replaced block created
const replaced = document.querySelector('[data-ai4a11y-replaced]');
if (replaced) return false;

// Button should remain enabled and labelled 'Plain language'
if (btn.disabled) return false;
if (btn.textContent.trim() !== 'Plain language') return false;

// Announcement should have been made to the live region
const liveRegion = document.querySelector('[aria-live]');
if (!liveRegion || !liveRegion.textContent.includes('Could not simplify')) return false;

return true;
